MATCH (source:PlantItem {tag: 'P-44001A'})
MATCH (v:Valve), (e:Equipment)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (e:Equipment {tag: 'E-31402'})-[:measured_by]->(i:ProcessInstrumentationFunction)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(f:ProcessInstrumentationFunction {loop_tag: 'TI-134065'})
