MATCH (head:ProcessInstrumentationFunction {loop_tag: 'LALL-380024'})
MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)
WHERE sensor.loop_tag = head.loop_tag
  AND EXISTS { (sensor)-[:send_signal_to*1..]->(head) }
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-41601B'})-[:measured_by]->(instrument:PlantItem)
