MATCH (a:PlantItem {tag: 'P-56801A'}), (b:PlantItem {tag: 'P-56901A'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'CHV-568001' AND y.tag <> 'CHV-568001')+ (b)
       } AS reachable

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem),
