MATCH (a:PlantItem {tag: 'D-59001'}), (b:PlantItem {tag: 'T-59001'})
RETURN EXISTS {
  MATCH (a)-[:line_to*1..]->(b)
  WHERE NOT EXISTS {
    MATCH (a)-[:line_to*0..]->(v:PlantItem {tag: 'GV-590003'})
    MATCH (v)-[:line_to*0..]->(b)
  }
} AS can_flow_without_GV590003

MATCH (a:PlantItem {tag: 'D-59001'}), (b:PlantItem {tag: 'T-59001'}), (v:PlantItem {tag: 'GV-590003'})
RETURN EXISTS {
  MATCH p = shortestPath((a)-[:line_to*1..]->(b))
  WHERE none(n IN nodes(p) WHERE n = v)
} AS can_flow_without_GV590003

